50	/**
51	 * Prepare instructions for code generation pass,
52	 * most of this modification breaks register dependencies,
53	 * so this pass must be just before CodeGen.
54	 */
55	@JadxVisitor(
56			name = "PrepareForCodeGen",
57			desc = "Prepare instructions for code generation pass",
58			runAfter = { CodeShrinkVisitor.class, ClassModifier.class, ProcessVariables.class }
59	)
60	public class PrepareForCodeGen extends AbstractVisitor {
61	
62		@Override
63		public String getName() {
64			return "PrepareForCodeGen";
65		}
66	
67		@Override
68		public boolean visit(ClassNode cls) throws JadxException {
69			if (cls.root().getArgs().isDebugInfo()) {
70				setClassSourceLine(cls);
71			}
72			collectFieldsUsageInAnnotations(cls);
73			return true;
74		}
75	
76		@Override
77		public void visit(MethodNode mth) throws JadxException {
78			if (mth.isNoCode()) {
79				return;
80			}
81			for (BlockNode block : mth.getBasicBlocks()) {
82				if (block.contains(AFlag.DONT_GENERATE)) {
83					continue;
84				}
85				removeInstructions(block);
86				checkInline(block);
87				removeParenthesis(block);
88				modifyArith(block);
89				checkConstUsage(block);
90				addNullCasts(mth, block);
91			}
92			moveConstructorInConstructor(mth);
93			collectFieldsUsageInAnnotations(mth, mth);
94		}
95	
96		private static void removeInstructions(BlockNode block) {
97			Iterator<InsnNode> it = block.getInstructions().iterator();
98			while (it.hasNext()) {
99				InsnNode insn = it.next();
100				switch (insn.getType()) {
101					case NOP:
102					case MONITOR_ENTER:
103					case MONITOR_EXIT:
104					case MOVE_EXCEPTION:
105						it.remove();
106						break;
107	
108					case CONSTRUCTOR:
109						ConstructorInsn co = (ConstructorInsn) insn;
110						if (co.isSelf()) {
111							it.remove();
112						}
113						break;
114	
115					case MOVE:
116						// remove redundant moves: unused result and same args names (a = a;)
117						RegisterArg result = insn.getResult();
118						if (result.getSVar().getUseCount() == 0
119								&& result.isNameEquals(insn.getArg(0))) {
120							it.remove();
121						}
122						break;
123	
124					default:
125						break;
126				}
127			}
128		}
129	
130		private static void checkInline(BlockNode block) {
131			List<InsnNode> list = block.getInstructions();
132			for (int i = 0; i < list.size(); i++) {
133				InsnNode insn = list.get(i);
134				// replace 'move' with inner wrapped instruction
135				if (insn.getType() == InsnType.MOVE
136						&& insn.getArg(0).isInsnWrap()) {
137					InsnNode wrapInsn = ((InsnWrapArg) insn.getArg(0)).getWrapInsn();
138					wrapInsn.setResult(insn.getResult());
139					wrapInsn.copyAttributesFrom(insn);
140					list.set(i, wrapInsn);
141				}
142			}
143		}
144	
145		/**
146		 * Add explicit type for non int constants
147		 */
148		private static void checkConstUsage(BlockNode block) {
149			for (InsnNode blockInsn : block.getInstructions()) {
150				blockInsn.visitInsns(insn -> {
151					if (forbidExplicitType(insn.getType())) {
152						return;
153					}
154					for (InsnArg arg : insn.getArguments()) {
155						if (arg.isLiteral() && arg.getType() != ArgType.INT) {
156							arg.add(AFlag.EXPLICIT_PRIMITIVE_TYPE);
157						}
158					}
159				});
160			}
161		}
162	
163		private static boolean forbidExplicitType(InsnType type) {
164			switch (type) {
165				case CONST:
166				case CAST:
167				case IF:
168				case FILLED_NEW_ARRAY:
169				case APUT:
170				case ARITH:
171					return true;
172				default:
173					return false;
174			}
175		}
176	
177		private static void removeParenthesis(BlockNode block) {
178			for (InsnNode insn : block.getInstructions()) {
179				removeParenthesis(insn);
180			}
181		}
182	
183		/**
184		 * Remove parenthesis for wrapped insn in arith '+' or '-'
185		 * ('(a + b) +c' => 'a + b + c')
186		 */
187		private static void removeParenthesis(InsnNode insn) {
188			if (insn.getType() == InsnType.ARITH) {
189				ArithNode arith = (ArithNode) insn;
190				ArithOp op = arith.getOp();
191				if (op == ArithOp.ADD || op == ArithOp.MUL || op == ArithOp.AND || op == ArithOp.OR) {
192					for (int i = 0; i < 2; i++) {
193						InsnArg arg = arith.getArg(i);
194						if (arg.isInsnWrap()) {
195							InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
196							if (wrapInsn.getType() == InsnType.ARITH && ((ArithNode) wrapInsn).getOp() == op) {
197								wrapInsn.add(AFlag.DONT_WRAP);
198							}
199							removeParenthesis(wrapInsn);
200						}
201					}
202				}
203			} else {
204				if (insn.getType() == InsnType.TERNARY) {
205					removeParenthesis(((TernaryInsn) insn).getCondition());
206				}
207				for (InsnArg arg : insn.getArguments()) {
208					if (arg.isInsnWrap()) {
209						InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
210						removeParenthesis(wrapInsn);
211					}
212				}
213			}
214		}
215	
216		private static void removeParenthesis(IfCondition cond) {
217			Mode mode = cond.getMode();
218			for (IfCondition c : cond.getArgs()) {
219				if (c.getMode() == mode) {
220					c.add(AFlag.DONT_WRAP);
221				}
222			}
223		}
224	
225		/**
226		 * Replace arithmetic operation with short form
227		 * ('a = a + 2' => 'a += 2')
228		 */
229		private static void modifyArith(BlockNode block) {
230			List<InsnNode> list = block.getInstructions();
231			for (InsnNode insn : list) {
232				if (insn.getType() == InsnType.ARITH
233						&& !insn.contains(AFlag.ARITH_ONEARG)
234						&& !insn.contains(AFlag.DECLARE_VAR)) {
235					RegisterArg res = insn.getResult();
236					InsnArg arg = insn.getArg(0);
237					boolean replace = false;
238					if (res.equals(arg)) {
239						replace = true;
240					} else if (arg.isRegister()) {
241						RegisterArg regArg = (RegisterArg) arg;
242						replace = res.sameCodeVar(regArg);
243					}
244					if (replace) {
245						insn.setResult(null);
246						insn.add(AFlag.ARITH_ONEARG);
247					}
248				}
249			}
250		}
251	
252		/**
253		 * Check that 'super' or 'this' call in constructor is a first instruction.
254		 * Otherwise, move to the top and add a warning.
255		 */
256		private void moveConstructorInConstructor(MethodNode mth) {
257			if (!mth.isConstructor()) {
258				return;
259			}
260			ConstructorInsn ctrInsn = searchConstructorCall(mth);
261			if (ctrInsn == null || ctrInsn.contains(AFlag.DONT_GENERATE)) {
262				return;
263			}
264			boolean firstInsn = BlockUtils.isFirstInsn(mth, ctrInsn);
265			DeclareVariablesAttr declVarsAttr = mth.getRegion().get(AType.DECLARE_VARIABLES);
266			if (firstInsn && declVarsAttr == null) {
267				// move not needed
268				return;
269			}
270			String callType = ctrInsn.getCallType().toString().toLowerCase();
271			BlockNode blockByInsn = BlockUtils.getBlockByInsn(mth, ctrInsn);
272			if (blockByInsn == null) {
273				mth.addWarn("Failed to move " + callType + " instruction to top");
274				return;
275			}
276	
277			if (!firstInsn) {
278				Set<RegisterArg> regArgs = new HashSet<>();
279				ctrInsn.getRegisterArgs(regArgs);
280				regArgs.remove(mth.getThisArg());
281				mth.getArgRegs().forEach(regArgs::remove);
282				if (!regArgs.isEmpty()) {
283					mth.addWarnComment("Illegal instructions before constructor call");
284					return;
285				}
286				mth.addWarnComment("'" + callType + "' call moved to the top of the method (can break code semantics)");
287			}
288	
289			// move confirmed
290			InsnList.remove(blockByInsn, ctrInsn);
291			mth.getRegion().getSubBlocks().add(0, new InsnContainer(ctrInsn));
292		}
293	
294		private @Nullable ConstructorInsn searchConstructorCall(MethodNode mth) {
295			for (BlockNode block : mth.getBasicBlocks()) {
296				for (InsnNode insn : block.getInstructions()) {
297					if (insn.getType() == InsnType.CONSTRUCTOR) {
298						ConstructorInsn ctrInsn = (ConstructorInsn) insn;
299						if (ctrInsn.isSuper() || ctrInsn.isThis()) {
300							return ctrInsn;
301						}
302						return null;
303					}
304				}
305			}
306			return null;
307		}
308	
309		/**
310		 * Use source line from top method
311		 */
312		private void setClassSourceLine(ClassNode cls) {
313			for (ClassNode innerClass : cls.getInnerClasses()) {
314				setClassSourceLine(innerClass);
315			}
316			int minLine = Stream.of(cls.getMethods(), cls.getInnerClasses(), cls.getFields())
317					.flatMap(Collection::stream)
318					.filter(mth -> !mth.contains(AFlag.DONT_GENERATE))
319					.filter(mth -> mth.getSourceLine() != 0)
320					.mapToInt(LineAttrNode::getSourceLine)
321					.min()
322					.orElse(0);
323			if (minLine != 0) {
324				cls.setSourceLine(minLine - 1);
325			}
326		}
327	
328		private void collectFieldsUsageInAnnotations(ClassNode cls) {
329			MethodNode useMth = cls.getDefaultConstructor();
330			if (useMth == null && !cls.getMethods().isEmpty()) {
331				useMth = cls.getMethods().get(0);
332			}
333			if (useMth == null) {
334				return;
335			}
336			collectFieldsUsageInAnnotations(useMth, cls);
337			MethodNode finalUseMth = useMth;
338			cls.getFields().forEach(f -> collectFieldsUsageInAnnotations(finalUseMth, f));
339		}
340	
341		private void collectFieldsUsageInAnnotations(MethodNode mth, AttrNode attrNode) {
342			AnnotationsAttr annotationsList = attrNode.get(JadxAttrType.ANNOTATION_LIST);
343			if (annotationsList == null) {
344				return;
345			}
346			for (IAnnotation annotation : annotationsList.getAll()) {
347				if (annotation.getVisibility() == AnnotationVisibility.SYSTEM) {
348					continue;
349				}
350				for (Map.Entry<String, EncodedValue> entry : annotation.getValues().entrySet()) {
351					checkEncodedValue(mth, entry.getValue());
352				}
353			}
354		}
355	
356		@SuppressWarnings("unchecked")
357		private void checkEncodedValue(MethodNode mth, EncodedValue encodedValue) {
358			switch (encodedValue.getType()) {
359				case ENCODED_FIELD:
360					Object fieldData = encodedValue.getValue();
361					FieldInfo fieldInfo;
362					if (fieldData instanceof IFieldRef) {
363						fieldInfo = FieldInfo.fromRef(mth.root(), (IFieldRef) fieldData);
364					} else {
365						fieldInfo = (FieldInfo) fieldData;
366					}
367					FieldNode fieldNode = mth.root().resolveField(fieldInfo);
368					if (fieldNode != null) {
369						fieldNode.addUseIn(mth);
370					}
371					break;
372	
373				case ENCODED_ANNOTATION:
374					IAnnotation annotation = (IAnnotation) encodedValue.getValue();
375					annotation.getValues().forEach((k, v) -> checkEncodedValue(mth, v));
376					break;
377	
378				case ENCODED_ARRAY:
379					List<EncodedValue> valueList = (List<EncodedValue>) encodedValue.getValue();
380					valueList.forEach(v -> checkEncodedValue(mth, v));
381					break;
382			}
383		}
384	
385		private void addNullCasts(MethodNode mth, BlockNode block) {
386			for (InsnNode insn : block.getInstructions()) {
387				switch (insn.getType()) {
388					case INVOKE:
389						verifyNullCast(mth, ((InvokeNode) insn).getInstanceArg());
390						break;
391	
392					case ARRAY_LENGTH:
393						verifyNullCast(mth, insn.getArg(0));
394						break;
395				}
396			}
397		}
398	
399		private void verifyNullCast(MethodNode mth, InsnArg arg) {
400			if (arg != null && arg.isZeroConst()) {
401				ArgType castType = arg.getType();
402				IndexInsnNode castInsn = new IndexInsnNode(InsnType.CAST, castType, 1);
403				castInsn.addArg(InsnArg.lit(0, castType));
404				arg.wrapInstruction(mth, castInsn);
405			}
406		}
407	}
