1	package jadx.core.dex.visitors;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import jadx.core.dex.attributes.AFlag;
7	import jadx.core.dex.info.MethodInfo;
8	import jadx.core.dex.instructions.BaseInvokeNode;
9	import jadx.core.dex.instructions.ConstStringNode;
10	import jadx.core.dex.instructions.IndexInsnNode;
11	import jadx.core.dex.instructions.InsnType;
12	import jadx.core.dex.instructions.InvokeNode;
13	import jadx.core.dex.instructions.args.ArgType;
14	import jadx.core.dex.instructions.args.InsnArg;
15	import jadx.core.dex.instructions.args.LiteralArg;
16	import jadx.core.dex.instructions.args.PrimitiveType;
17	import jadx.core.dex.instructions.args.RegisterArg;
18	import jadx.core.dex.instructions.args.SSAVar;
19	import jadx.core.dex.instructions.mods.ConstructorInsn;
20	import jadx.core.dex.nodes.BlockNode;
21	import jadx.core.dex.nodes.IFieldInfoRef;
22	import jadx.core.dex.nodes.InsnNode;
23	import jadx.core.dex.nodes.MethodNode;
24	import jadx.core.dex.visitors.finaly.MarkFinallyVisitor;
25	import jadx.core.dex.visitors.ssa.SSATransform;
26	import jadx.core.dex.visitors.typeinference.TypeInferenceVisitor;
27	import jadx.core.utils.InsnRemover;
28	import jadx.core.utils.exceptions.JadxException;
29	import jadx.core.utils.exceptions.JadxRuntimeException;
30	
31	@JadxVisitor(
32			name = "Constants Inline",
33			desc = "Inline constant registers into instructions",
34			runAfter = {
35					SSATransform.class,
36					MarkFinallyVisitor.class
37			},
38			runBefore = TypeInferenceVisitor.class
39	)
40	public class ConstInlineVisitor extends AbstractVisitor {
41	
42		@Override
43		public void visit(MethodNode mth) throws JadxException {
44			if (mth.isNoCode()) {
45				return;
46			}
47			process(mth);
48		}
49	
50		public static void process(MethodNode mth) {
51			List<InsnNode> toRemove = new ArrayList<>();
52			for (BlockNode block : mth.getBasicBlocks()) {
53				toRemove.clear();
54				for (InsnNode insn : block.getInstructions()) {
55					checkInsn(mth, insn, toRemove);
56				}
57				InsnRemover.removeAllAndUnbind(mth, block, toRemove);
58			}
59		}
60	
61		private static void checkInsn(MethodNode mth, InsnNode insn, List<InsnNode> toRemove) {
62			if (insn.contains(AFlag.DONT_INLINE)
63					|| insn.contains(AFlag.DONT_GENERATE)
64					|| insn.getResult() == null) {
65				return;
66			}
67			SSAVar sVar = insn.getResult().getSVar();
68			InsnArg constArg;
69			Runnable onSuccess = null;
70			switch (insn.getType()) {
71				case CONST:
72				case MOVE: {
73					constArg = insn.getArg(0);
74					if (!constArg.isLiteral()) {
75						return;
76					}
77					if (constArg.isZeroLiteral() && forbidNullInlines(sVar)) {
78						// all usages forbids inlining
79						return;
80					}

80					}
81					break;
82				}
83				case CONST_STR: {
84					String s = ((ConstStringNode) insn).getString();
85					IFieldInfoRef f = mth.getParentClass().getConstField(s);
86					if (f == null) {
87						InsnNode copy = insn.copyWithoutResult();
88						constArg = InsnArg.wrapArg(copy);
89					} else {
90						InsnNode constGet = new IndexInsnNode(InsnType.SGET, f.getFieldInfo(), 0);
91						constArg = InsnArg.wrapArg(constGet);
92						constArg.setType(ArgType.STRING);
93						onSuccess = () -> ModVisitor.addFieldUsage(f, mth);
94					}
95					break;
96				}
97				case CONST_CLASS: {
98					if (sVar.isUsedInPhi()) {
99						return;
100					}
101					constArg = InsnArg.wrapArg(insn.copyWithoutResult());
102					constArg.setType(ArgType.CLASS);
103					break;
104				}
105				default:
106					return;
107			}
108	
109			// all check passed, run replace
110			if (replaceConst(mth, insn, constArg)) {
111				toRemove.add(insn);
112				if (onSuccess != null) {
113					onSuccess.run();
114				}
115			}
116		}
117	
118		/**
119		 * Don't inline null object
120		 */
121		private static boolean forbidNullInlines(SSAVar sVar) {
122			List<RegisterArg> useList = sVar.getUseList();
123			if (useList.isEmpty()) {
124				return false;
125			}
126			int k = 0;
127			for (RegisterArg useArg : useList) {
128				InsnNode insn = useArg.getParentInsn();
129				if (insn != null && forbidNullArgInline(insn, useArg)) {
130					k++;
131				}
132			}
133			return k == useList.size();
134		}
135	
136		private static boolean forbidNullArgInline(InsnNode insn, RegisterArg useArg) {
137			if (insn.getType() == InsnType.MOVE) {
138				// result is null, chain checks
139				return forbidNullInlines(insn.getResult().getSVar());
140			}
141			if (!canUseNull(insn, useArg)) {
142				useArg.add(AFlag.DONT_INLINE_CONST);
143				return true;
144			}
145			return false;
146		}
147	
148		private static boolean canUseNull(InsnNode insn, RegisterArg useArg) {
149			switch (insn.getType()) {
150				case INVOKE:
151					return ((InvokeNode) insn).getInstanceArg() != useArg;
152	
153				case ARRAY_LENGTH:
154				case AGET:
155				case APUT:
156				case IGET:
157				case SWITCH:
158				case MONITOR_ENTER:
159				case MONITOR_EXIT:
160				case INSTANCE_OF:
161					return insn.getArg(0) != useArg;
162	
163				case IPUT:
164					return insn.getArg(1) != useArg;
165			}
166			return true;
167		}
168	
169		private static boolean replaceConst(MethodNode mth, InsnNode constInsn, InsnArg constArg) {
170			SSAVar ssaVar = constInsn.getResult().getSVar();
171			if (ssaVar.getUseCount() == 0) {
172				return true;
173			}
174			List<RegisterArg> useList = new ArrayList<>(ssaVar.getUseList());
175			int replaceCount = 0;
176			for (RegisterArg arg : useList) {
177				if (canInline(mth, arg) && replaceArg(mth, arg, constArg, constInsn)) {
178					replaceCount++;
179				}
180			}
181			if (replaceCount == useList.size()) {
182				return true;
183			}
184			// hide insn if used only in not generated insns
185			if (ssaVar.getUseList().stream().allMatch(ConstInlineVisitor::canIgnoreInsn)) {
186				constInsn.add(AFlag.DONT_GENERATE);
187			}
188			return false;
189		}
190	
191		private static boolean canIgnoreInsn(RegisterArg reg) {
192			InsnNode parentInsn = reg.getParentInsn();
193			if (parentInsn == null || parentInsn.getType() == InsnType.PHI) {
194				return false;
195			}
196			if (reg.isLinkedToOtherSsaVars()) {
197				return false;
198			}
199			return parentInsn.contains(AFlag.DONT_GENERATE);

1	package jadx.core.dex.nodes;
2	
3	import java.util.ArrayList;
4	import java.util.Collections;
5	import java.util.HashMap;
6	import java.util.LinkedHashSet;
7	import java.util.List;
8	import java.util.Map;
9	import java.util.Set;
