151		private void splitAndApplyNames(RootNode root, ArgType type, boolean canBeInner) {
152			String fullObjectName = type.getObject();
153			String clsPkg;
154			String clsName;
155			int dot = fullObjectName.lastIndexOf('.');
156			if (dot == -1) {
157				clsPkg = "";
158				clsName = fullObjectName;
159			} else {
160				clsPkg = fullObjectName.substring(0, dot);
161				clsName = fullObjectName.substring(dot + 1);
162			}
163	
164			boolean innerCls = false;
165			if (canBeInner) {
166				int sep = clsName.lastIndexOf('$');
167				if (sep > 0 && sep != clsName.length() - 1) {
168					String parClsName = clsPkg + '.' + clsName.substring(0, sep);
169					if (clsPkg.isEmpty()) {
170						parClsName = clsName.substring(0, sep);
171					}
172					pkg = null;
173					parentClass = fromName(root, parClsName);
174					clsName = clsName.substring(sep + 1);
175					innerCls = true;
176				}
177			}
178			if (!innerCls) {
179				pkg = clsPkg;

178			if (!innerCls) {
179				pkg = clsPkg;
180				parentClass = null;
181			}
182			this.name = clsName;
183			this.fullName = makeFullName();
184		}
