186		private static String makeFullClsName(String pkg, String shortName, ClassInfo parentClass, boolean alias, boolean raw) {
187			if (parentClass != null) {
188				String parentFullName;
189				char innerSep = raw ? '$' : '.';
190				if (alias) {
191					parentFullName = raw ? parentClass.makeAliasRawFullName() : parentClass.getAliasFullName();
192				} else {
193					parentFullName = raw ? parentClass.makeRawFullName() : parentClass.getFullName();
194				}
195				return parentFullName + innerSep + shortName;
196			}
197			return pkg.isEmpty() ? shortName : pkg + '.' + shortName;
198		}
