33	@JadxVisitor(
34			name = "ReplaceNewArray",
35			desc = "Replace new-array and sequence of array-put to new filled-array instruction",
36			runAfter = CodeShrinkVisitor.class
37	)
38	public class ReplaceNewArray extends AbstractVisitor {
39	
40		@Override
41		public void visit(MethodNode mth) throws JadxException {
42			if (!CodeFeaturesAttr.contains(mth, CodeFeature.NEW_ARRAY)) {
43				return;
44			}
45			InsnRemover remover = new InsnRemover(mth);
46			int k = 0;
47			while (true) {
48				boolean changed = false;
49				for (BlockNode block : mth.getBasicBlocks()) {
50					List<InsnNode> insnList = block.getInstructions();
51					int size = insnList.size();
52					for (int i = 0; i < size; i++) {
53						changed |= processInsn(mth, insnList, i, remover);
54					}
55					remover.performForBlock(block);
56				}
57				if (changed) {
58					CodeShrinkVisitor.shrinkMethod(mth);
59				} else {
60					break;
61				}
62				if (k++ > 100) {
63					mth.addWarnComment("Reached limit for ReplaceNewArray iterations");
64					break;
65				}
66			}
67		}
68	
69		private static boolean processInsn(MethodNode mth, List<InsnNode> instructions, int i, InsnRemover remover) {
70			InsnNode insn = instructions.get(i);
71			if (insn.getType() == InsnType.NEW_ARRAY && !insn.contains(AFlag.REMOVE)) {
72				return processNewArray(mth, (NewArrayNode) insn, instructions, remover);
73			}
74			return false;
75		}
76	
77		private static boolean processNewArray(MethodNode mth,
78				NewArrayNode newArrayInsn, List<InsnNode> instructions, InsnRemover remover) {
79			Object arrayLenConst = InsnUtils.getConstValueByArg(mth.root(), newArrayInsn.getArg(0));
80			if (!(arrayLenConst instanceof LiteralArg)) {
81				return false;
82			}
83			int len = (int) ((LiteralArg) arrayLenConst).getLiteral();
84			if (len == 0) {
85				return false;
86			}
87			ArgType arrType = newArrayInsn.getArrayType();
88			ArgType elemType = arrType.getArrayElement();
89			boolean allowMissingKeys = arrType.getArrayDimension() == 1 && elemType.isPrimitive();
90			int minLen = allowMissingKeys ? len / 2 : len;
91	
92			RegisterArg arrArg = newArrayInsn.getResult();
93			List<RegisterArg> useList = arrArg.getSVar().getUseList();
94			if (useList.size() < minLen) {
95				return false;
96			}
97			// quick check if APUT is used
98			boolean foundPut = false;
99			for (RegisterArg registerArg : useList) {
100				InsnNode parentInsn = registerArg.getParentInsn();
101				if (parentInsn != null && parentInsn.getType() == InsnType.APUT) {
102					foundPut = true;
103					break;
104				}
105			}
106			if (!foundPut) {
107				return false;
108			}
109			// collect put instructions sorted by array index
110			SortedMap<Long, InsnNode> arrPuts = new TreeMap<>();
111			InsnNode firstNotAPutUsage = null;
112			for (RegisterArg registerArg : useList) {
113				InsnNode parentInsn = registerArg.getParentInsn();
114				if (parentInsn == null
115						|| parentInsn.getType() != InsnType.APUT
116						|| !arrArg.sameRegAndSVar(parentInsn.getArg(0))) {
117					if (firstNotAPutUsage == null) {
118						firstNotAPutUsage = parentInsn;
119					}
120					continue;
121				}
122				Object constVal = InsnUtils.getConstValueByArg(mth.root(), parentInsn.getArg(1));
123				if (!(constVal instanceof LiteralArg)) {
124					return false;
125				}
126				long index = ((LiteralArg) constVal).getLiteral();
127				if (index >= len) {
128					return false;
129				}
130				if (arrPuts.containsKey(index)) {
131					// stop on index rewrite
132					break;
133				}
134				arrPuts.put(index, parentInsn);
135			}
136			if (arrPuts.size() < minLen) {
137				return false;
138			}
139			if (!verifyPutInsns(arrArg, instructions, arrPuts)) {
140				return false;
141			}
142	
143			// checks complete, apply
144			InsnNode filledArr = new FilledNewArrayNode(elemType, len);
145			filledArr.setResult(arrArg.duplicate());
146			filledArr.copyAttributesFrom(newArrayInsn);
147			filledArr.inheritMetadata(newArrayInsn);
148			filledArr.setOffset(newArrayInsn.getOffset());
149	
150			long prevIndex = -1;
151			for (Map.Entry<Long, InsnNode> entry : arrPuts.entrySet()) {
152				long index = entry.getKey();
153				if (index != prevIndex) {
154					// use zero for missing keys
155					for (long i = prevIndex + 1; i < index; i++) {
156						filledArr.addArg(InsnArg.lit(0, elemType));
157					}
158				}
159				InsnNode put = entry.getValue();
160				filledArr.addArg(replaceConstInArg(mth, put.getArg(2)));
161				remover.addAndUnbind(put);
162				prevIndex = index;
163			}
164			// add missing trailing zeros
165			for (long i = prevIndex + 1; i < len; i++) {
166				filledArr.addArg(InsnArg.lit(0, elemType));
167			}
168			remover.addAndUnbind(newArrayInsn);
169	
170			// place new insn at last array put or before first usage
171			InsnNode lastPut = arrPuts.get(arrPuts.lastKey());
172			int newInsnPos = InsnList.getIndex(instructions, lastPut);
173			if (firstNotAPutUsage != null) {
174				int idx = InsnList.getIndex(instructions, firstNotAPutUsage);
175				if (idx != -1) {
176					// TODO: check that all args already assigned
177					newInsnPos = Math.min(idx, newInsnPos);
178				}
179			}
180			instructions.add(newInsnPos, filledArr);
181			return true;
182		}
183	
184		private static boolean verifyPutInsns(RegisterArg arrReg, List<InsnNode> insnList, SortedMap<Long, InsnNode> arrPuts) {
185			List<InsnNode> puts = new ArrayList<>(arrPuts.values());
186			int putsCount = puts.size();
187			// expect all puts to be in the same block
188			if (insnList.size() < putsCount) {
189				return false;
190			}
191			Set<InsnNode> insnSet = Collections.newSetFromMap(new IdentityHashMap<>());
192			insnSet.addAll(insnList);
193			if (!insnSet.containsAll(puts)) {
194				return false;
195			}
196			// array arg shouldn't be used in puts insns
197			for (InsnNode put : puts) {
198				InsnArg putArg = put.getArg(2);
199				if (putArg.isUseVar(arrReg)) {
200					return false;
201				}
202			}
203			return true;
204		}
205	
206		private static InsnArg replaceConstInArg(MethodNode mth, InsnArg valueArg) {
207			if (valueArg.isLiteral()) {
208				IFieldInfoRef f = mth.getParentClass().getConstFieldByLiteralArg((LiteralArg) valueArg);
209				if (f != null) {
210					InsnNode fGet = new IndexInsnNode(InsnType.SGET, f.getFieldInfo(), 0);
211					InsnArg arg = InsnArg.wrapArg(fGet);
212					ModVisitor.addFieldUsage(f, mth);
213					return arg;
214				}
215			}
216			return valueArg.duplicate();
217		}
218	}
