41	
42		public static void shrinkMethod(MethodNode mth) {
43			if (mth.isNoCode()) {
44				return;
45			}
46			mth.remove(AFlag.REQUEST_CODE_SHRINK);
47			for (BlockNode block : mth.getBasicBlocks()) {
48				shrinkBlock(mth, block);
49				simplifyMoveInsns(mth, block);
50			}
51		}
52	
53		private static void shrinkBlock(MethodNode mth, BlockNode block) {
54			if (block.getInstructions().isEmpty()) {
55				return;
56			}
57			InsnList insnList = new InsnList(block.getInstructions());
58			int insnCount = insnList.size();
59			List<ArgsInfo> argsList = new ArrayList<>(insnCount);
60			for (int i = 0; i < insnCount; i++) {
61				argsList.add(new ArgsInfo(insnList.get(i), argsList, i));
62			}
63			List<WrapInfo> wrapList = new ArrayList<>();
64			for (ArgsInfo argsInfo : argsList) {
65				List<RegisterArg> args = argsInfo.getArgs();
66				for (int i = args.size() - 1; i >= 0; i--) {
67					RegisterArg arg = args.get(i);
68					checkInline(mth, block, insnList, wrapList, argsInfo, arg);
69				}
70			}
71			if (!wrapList.isEmpty()) {
72				for (WrapInfo wrapInfo : wrapList) {
73					inline(mth, wrapInfo.getArg(), wrapInfo.getInsn(), block);
74				}
75			}
76		}
77	
78		private static void checkInline(MethodNode mth, BlockNode block, InsnList insnList,
79				List<WrapInfo> wrapList, ArgsInfo argsInfo, RegisterArg arg) {
80			if (arg.contains(AFlag.DONT_INLINE)

80			if (arg.contains(AFlag.DONT_INLINE)
81					|| arg.getParentInsn() == null
82					|| arg.getParentInsn().contains(AFlag.DONT_GENERATE)) {
83				return;
84			}
85			SSAVar sVar = arg.getSVar();
86			if (sVar == null || sVar.getAssign().contains(AFlag.DONT_INLINE)) {
87				return;
88			}
89			InsnNode assignInsn = sVar.getAssign().getParentInsn();
90			if (assignInsn == null
91					|| assignInsn.contains(AFlag.DONT_INLINE)
92					|| assignInsn.contains(AFlag.WRAPPED)) {
93				return;
94			}
95			boolean assignInline = assignInsn.contains(AFlag.FORCE_ASSIGN_INLINE);
96			if (!assignInline && sVar.isUsedInPhi()) {
97				return;
98			}
99			// allow inline only one use arg
100			int useCount = 0;
101			for (RegisterArg useArg : sVar.getUseList()) {
102				InsnNode parentInsn = useArg.getParentInsn();
103				if (parentInsn != null && parentInsn.contains(AFlag.DONT_GENERATE)) {
104					continue;
105				}
106				if (!assignInline && useArg.contains(AFlag.DONT_INLINE_CONST)) {
107					return;
108				}
109				useCount++;
110			}
111			if (!assignInline && useCount != 1) {
112				return;
113			}
114			if (!assignInline && sVar.getName() != null) {
115				if (searchArgWithName(assignInsn, sVar.getName())) {
116					// allow inline if name is reused in result
117				} else if (varWithSameNameExists(mth, sVar)) {
118					// allow inline if var name is duplicated
119				} else {
120					// reject inline of named variable
121					return;
122				}
123			}
124			if (!checkLambdaInline(arg, assignInsn)) {
125				return;
126			}
127	
128			int assignPos = insnList.getIndex(assignInsn);
129			if (assignPos != -1) {
130				WrapInfo wrapInfo = argsInfo.checkInline(assignPos, arg);
131				if (wrapInfo != null) {
132					wrapList.add(wrapInfo);
133				}
134			} else {
135				// another block
136				BlockNode assignBlock = BlockUtils.getBlockByInsn(mth, assignInsn);
137				if (assignBlock != null
138						&& assignInsn != arg.getParentInsn()
139						&& canMoveBetweenBlocks(mth, assignInsn, assignBlock, block, argsInfo.getInsn())) {
140					if (assignInline) {
141						assignInline(mth, arg, assignInsn, assignBlock);
142					} else {
143						inline(mth, arg, assignInsn, assignBlock);
144					}
145				}
146			}
147		}
