154			if (assignInsn.getType() == InsnType.INVOKE && assignInsn instanceof InvokeCustomNode) {
155				for (RegisterArg useArg : arg.getSVar().getUseList()) {
156					InsnNode parentInsn = useArg.getParentInsn();
157					if (parentInsn != null && parentInsn.getType() == InsnType.INVOKE) {
158						InvokeNode invokeNode = (InvokeNode) parentInsn;
159						InsnArg instArg = invokeNode.getInstanceArg();
160						if (instArg != null && instArg == useArg) {
