80		private void formatAnnotation(ICodeWriter code, IAnnotation a) {
81			code.add('@');
82			ClassNode annCls = cls.root().resolveClass(a.getAnnotationClass());
83			if (annCls != null) {
84				classGen.useClass(code, annCls);
85			} else {
