143		// TODO: refactor this boilerplate code
144		public void encodeValue(RootNode root, ICodeWriter code, EncodedValue encodedValue) {
145			if (encodedValue == null) {
146				code.add("null");
147				return;
148			}
149	
150			StringUtils stringUtils = getStringUtils();
151			Object value = encodedValue.getValue();
152			switch (encodedValue.getType()) {
153				case ENCODED_NULL:
154					code.add("null");
155					break;
156				case ENCODED_BOOLEAN:
157					code.add(Boolean.TRUE.equals(value) ? "true" : "false");
158					break;
159				case ENCODED_BYTE:
160					code.add(stringUtils.formatByte((Byte) value, false));
161					break;
162				case ENCODED_SHORT:
163					code.add(stringUtils.formatShort((Short) value, false));
164					break;
165				case ENCODED_CHAR:
166					code.add(stringUtils.unescapeChar((Character) value));
167					break;
168				case ENCODED_INT:
169					code.add(stringUtils.formatInteger((Integer) value, false));
170					break;
171				case ENCODED_LONG:
172					code.add(stringUtils.formatLong((Long) value, false));
173					break;
174				case ENCODED_FLOAT:
175					code.add(StringUtils.formatFloat((Float) value));
176					break;
177				case ENCODED_DOUBLE:
178					code.add(StringUtils.formatDouble((Double) value));
179					break;
180				case ENCODED_STRING:
181					code.add(stringUtils.unescapeString((String) value));
182					break;
183				case ENCODED_TYPE:
184					classGen.useType(code, ArgType.parse((String) value));
185					code.add(".class");
186					break;
187				case ENCODED_ENUM:
188				case ENCODED_FIELD:
189					// must be a static field
190					if (value instanceof IFieldRef) {
191						FieldInfo fieldInfo = FieldInfo.fromRef(root, (IFieldRef) value);
192						InsnGen.makeStaticFieldAccess(code, fieldInfo, classGen);
193					} else if (value instanceof FieldInfo) {
194						InsnGen.makeStaticFieldAccess(code, (FieldInfo) value, classGen);
195					} else {
196						throw new JadxRuntimeException("Unexpected field type class: " + value.getClass());
197					}
198					break;
199				case ENCODED_METHOD:

199				case ENCODED_METHOD:
200					// TODO
201					break;
202				case ENCODED_ARRAY:
203					code.add('{');
204					Iterator<?> it = ((Iterable<?>) value).iterator();
205					while (it.hasNext()) {
206						EncodedValue v = (EncodedValue) it.next();
207						encodeValue(cls.root(), code, v);
208						if (it.hasNext()) {
209							code.add(", ");
210						}
211					}
212					code.add('}');
213					break;
214				case ENCODED_ANNOTATION:
215					formatAnnotation(code, (IAnnotation) value);
216					break;
217	
218				default:
219					throw new JadxRuntimeException("Can't decode value: " + encodedValue.getType() + " (" + encodedValue + ')');
220			}
221		}
