38		private void addNamesUsedInClass() {
39			ClassNode parentClass = mth.getParentClass();
40			for (FieldNode field : parentClass.getFields()) {
41				if (field.isStatic()) {
42					varNames.add(field.getAlias());
43				}
44			}
45			for (ClassNode innerClass : parentClass.getInnerClasses()) {
46				varNames.add(innerClass.getClassInfo().getAliasShortName());
47			}
48			// add all root package names to avoid collisions with full class names
49			varNames.addAll(mth.root().getCacheStorage().getRootPkgs());
