89		private static final Pattern ENDS_WITH_NUMBER = Pattern.compile(".*(\\d+)$");
90	
91		private String getUniqueVarName(String name) {
92			if (!varNames.contains(name)) {
93				varNames.add(name);
94				return name;
95			}
96			// code duplication reuse same variable in different places
97			// parse variable name and increment index
98			String base;
99			int i;
100			Matcher matcher = ENDS_WITH_NUMBER.matcher(name);
101			if (matcher.matches()) {
102				base = name.substring(0, matcher.start(1));
103				i = 1 + Integer.parseInt(matcher.group(1));
104			} else {
105				base = name;
106				i = 2;
107			}
108			while (true) {
109				String newName = base + i++;
110				if (!varNames.contains(newName)) {
111					varNames.add(newName);
112					return newName;
113				}
114			}
115		}
