125		private String getFallbackName(CodeVar var) {
126			List<SSAVar> ssaVars = var.getSsaVars();
127			if (ssaVars.isEmpty()) {
128				return "v";
129			}
130			return getFallbackName(ssaVars.get(0).getAssign());
131		}
