53				"java.lang.Double", "d",
54				"java.lang.StringBuilder", "sb",
55				"java.lang.Exception", "exc");
56	
57		private static final Set<String> GOOD_VAR_NAMES = Set.of(
58				"size", "length", "list", "map", "next");
59		private static final List<String> INVOKE_PREFIXES = List.of(
60				"get", "set", "to", "parse", "read", "format");
