124		private String makeNameFromInsn(SSAVar ssaVar, InsnNode insn) {
125			switch (insn.getType()) {
126				case INVOKE:
127					return makeNameFromInvoke(ssaVar, (InvokeNode) insn);
128	
129				case CONSTRUCTOR:
130					ConstructorInsn co = (ConstructorInsn) insn;
131					MethodNode callMth = root.getMethodUtils().resolveMethod(co);
132					if (callMth != null && callMth.contains(AFlag.ANONYMOUS_CONSTRUCTOR)) {
133						// don't use name of anonymous class
134						return null;
135					}
136					return makeNameForClass(co.getClassType());
137	
138				case ARRAY_LENGTH:
139					return "length";
140	
141				case ARITH:
142				case TERNARY:
143				case CAST:
144					for (InsnArg arg : insn.getArguments()) {
145						if (arg.isInsnWrap()) {
146							InsnNode wrapInsn = ((InsnWrapArg) arg).getWrapInsn();
147							String wName = makeNameFromInsn(ssaVar, wrapInsn);
148							if (wName != null) {
149								return wName;
150							}
151						}
152					}
