164			}
165			if (type.isArray()) {
166				return makeNameForType(type.getArrayRootElement()) + "Arr";
167			}
168			return makeNameForObject(type);
169		}
170	
171		private String makeNameForObject(ArgType type) {
172			if (type.isGenericType()) {
173				return StringUtils.escape(type.getObject().toLowerCase());
174			}
175			if (type.isObject()) {
176				String alias = getAliasForObject(type.getObject());
177				if (alias != null) {
178					return alias;
179				}
180				return makeNameForCheckedClass(ClassInfo.fromType(root, type));
181			}
182			return StringUtils.escape(type.toString());
183		}
184	
185		private String makeNameForCheckedClass(ClassInfo classInfo) {
186			String shortName = classInfo.getAliasShortName();
187			String vName = fromName(shortName);
188			if (vName != null) {
189				return vName;
190			}
191			String lower = StringUtils.escape(shortName.toLowerCase());
192			if (shortName.equals(lower)) {
193				return lower + "Var";
194			}
195			return lower;
196		}
197	
198		private String makeNameForClass(ClassInfo classInfo) {
199			String alias = getAliasForObject(classInfo.getFullName());

199			String alias = getAliasForObject(classInfo.getFullName());
200			if (alias != null) {
201				return alias;
202			}
203			return makeNameForCheckedClass(classInfo);
204		}
205	
206		private static String fromName(String name) {
207			if (name == null || name.isEmpty()) {
208				return null;
209			}
210			if (name.toUpperCase().equals(name)) {
211				// all characters are upper case
212				return name.toLowerCase();
213			}
214			String v1 = Character.toLowerCase(name.charAt(0)) + name.substring(1);
215			if (!v1.equals(name)) {
216				return v1;
217			}
218			if (name.length() < 3) {
219				return name + "Var";
220			}
221			return null;
222		}
223	
224		private static String getAliasForObject(String name) {
225			return OBJ_ALIAS.get(name);
226		}
227	
228		private String makeNameFromInvoke(SSAVar ssaVar, InvokeNode inv) {
229			MethodInfo callMth = inv.getCallMth();
230			String name = callMth.getAlias();
231			ClassInfo declClass = callMth.getDeclClass();
232			if ("getInstance".equals(name)) {
233				// e.g. Cipher.getInstance
234				return makeNameForClass(declClass);
235			}
236			String shortName = cutPrefix(name);
237			if (shortName != null) {
238				return fromName(shortName);
239			}
240			if ("iterator".equals(name)) {
241				return "it";
242			}
243			if ("toString".equals(name)) {
244				return makeNameForClass(declClass);
245			}
246			if ("forName".equals(name) && declClass.getType().equals(ArgType.CLASS)) {
247				return OBJ_ALIAS.get(Consts.CLASS_CLASS);
248			}
249			// use method name as a variable name not the best idea in most cases
250			if (!GOOD_VAR_NAMES.contains(name)) {
251				String typeName = makeNameForType(ssaVar.getCodeVar().getType());
252				if (!typeName.equalsIgnoreCase(name)) {
253					return typeName + StringUtils.capitalizeFirstChar(name);
254				}
255			}
256			return name;
257		}
258	
259		private @Nullable String cutPrefix(String name) {
260			for (String prefix : INVOKE_PREFIXES) {
261				if (name.startsWith(prefix)) {
262					return name.substring(prefix.length());
263				}
264			}
265			return null;
266		}
267	
268		@Override
269		public String getName() {
270			return "ApplyVariableNames";
271		}
